  },
  "q4_non_clinical": {
    "answer": "No",
    "evidence": "Description: Patients undergoing coronary angiography were selected; RNA extracted from 110 patients with CAD and from 112 controls.",
    "justification": "This is a clinical study using patient blood samples (in vivo), not patient-derived in vitro cell lines or experimental disease models."
  },
  "q5_case_control_design": {
    "answer": "Yes",
    "evidence": "Parallel group design; RNA extracted from 110 patients with CAD (CADi>23) and from 112 partially matched controls without CAD (CADi=0); Experimental Factors include PATIENT GROUP and CADI.",
    "justification": "The study compares cases (CAD patients) to controls in a parallel group case/control design."
