  "q6_irrelevant_brain_region": {
    "answer": "Yes",
    "evidence": "Samples are circulating leukocytes/peripheral blood (no brain regions sampled); Organism part not specified as CNS.",
    "justification": "No brain regions are sampled; therefore it does not involve any brain regions (irrelevant for ALS-FTD CNS regions)."
  },
  "q7_incompatible_technology": {
    "answer": "No",
    "evidence": "Study type: transcription profiling by array; Technology: Array assay; Affymetrix U133A microarrays used.",
    "justification": "The technology is microarray expression profiling, which is compatible with inclusion; no RNA-seq or proteomics."
  },
  "q8_inclusion_justification": {
    "justification": "Although this is a human microarray, case/control study, it does not meet disease or tissue inclusion criteria: it studies coronary artery disease using peripheral blood leukocytes rather than ALS-FTD and CNS tissue. Therefore it should be excluded."
  },
  "q9_include_dataset": {
    "answer": "No"
  }
}

